# Static inspection only: none of these functions load an XR/runtime DLL.
function Get-LocalRuntimeProfile([string]$ManifestPath,[string]$LoaderPath) {
    if($env:XR_RUNTIME_JSON){throw 'XR_RUNTIME_JSON override present; review the environment first'}
    $active=(Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Khronos\OpenXR\1' -ErrorAction Stop).ActiveRuntime
    if(-not $ManifestPath){$ManifestPath=$active}
    $ManifestPath=[IO.Path]::GetFullPath($ManifestPath)
    if($active -ine $ManifestPath){throw 'Selected manifest must match active SteamVR runtime'}
    $user=(Get-ItemProperty -LiteralPath 'HKCU:\SOFTWARE\Khronos\OpenXR\1' -ErrorAction SilentlyContinue).ActiveRuntime
    if($user -and $user -ine $ManifestPath){throw 'Different per-user runtime selection; review first'}
    $manifest=[IO.File]::ReadAllText($ManifestPath)|ConvertFrom-Json
    if($manifest.runtime.VALVE_runtime_is_steamvr -ne $true){throw 'This initial live-test backend requires SteamVR'}
    $directory=Split-Path -Parent $ManifestPath
    $runtimePath=[IO.Path]::GetFullPath((Join-Path $directory $manifest.runtime.library_path))
    if(-not $LoaderPath){$LoaderPath=Join-Path $directory 'bin\win64\openxr_loader.dll'}
    $LoaderPath=[IO.Path]::GetFullPath($LoaderPath)
    $implicit=@(foreach($hive in @('HKLM','HKCU')){$key=$hive+':\SOFTWARE\Khronos\OpenXR\1\ApiLayers\Implicit';if(Test-Path -LiteralPath $key){$properties=Get-ItemProperty -LiteralPath $key;foreach($property in $properties.PSObject.Properties){if($property.Name -notmatch '^PS'){[pscustomobject]@{Hive=$hive;Manifest=$property.Name;Value=$property.Value}}}}})
    return [pscustomobject]@{SchemaVersion=1;Provider='SteamVR';Manifest=$ManifestPath;Loader=$LoaderPath;Runtime=$runtimePath;ManifestSHA256=(Get-FileHash -LiteralPath $ManifestPath -Algorithm SHA256).Hash;LoaderSHA256=(Get-FileHash -LiteralPath $LoaderPath -Algorithm SHA256).Hash;RuntimeSHA256=(Get-FileHash -LiteralPath $runtimePath -Algorithm SHA256).Hash;ImplicitLayers=$implicit;EnableApiLayers=$env:XR_ENABLE_API_LAYERS;DisableApiLayers=$env:XR_DISABLE_API_LAYERS;PhysicalHdrVerified=$false}
}
function Read-ReviewedRuntimeProfile([string]$Path) {
    if(-not $Path){throw 'Provide an explicitly reviewed local -Profile file generated by Inspect'}
    $profile=[IO.File]::ReadAllText([IO.Path]::GetFullPath($Path))|ConvertFrom-Json
    if($profile.SchemaVersion -ne 1 -or $profile.Provider -ne 'SteamVR'){throw 'Unknown runtime profile schema/provider'}
    $current=Get-LocalRuntimeProfile $profile.Manifest $profile.Loader
    foreach($field in @('Manifest','Loader','Runtime','ManifestSHA256','LoaderSHA256','RuntimeSHA256')){if($current.$field -ine $profile.$field){throw ('Runtime changed: '+$field+'; review a new profile')}}
    foreach($name in @('vrserver','vrcompositor')){if(-not(Get-Process -Name $name -ErrorAction SilentlyContinue)){throw ($name+' must already be running; no automatic launch')}}
    return $profile
}
